/**
 * Surface textures for the reef (generated by scripts/generate-textures.ts and
 * served from public/textures), plus the shader patch that maps them onto
 * simple geometry without seams: triplanar projection in object space, so a
 * rock or a coral branch gets an even texture from every side.
 */
import * as THREE from 'three';
import { sharedTime, sunlight } from './util.ts';

export interface ReefTextures {
  sand?: THREE.Texture;
  sandN?: THREE.Texture;
  rubble?: THREE.Texture;
  rubbleN?: THREE.Texture;
  rock?: THREE.Texture;
  rockN?: THREE.Texture;
  coral?: THREE.Texture;
  coralN?: THREE.Texture;
  brain?: THREE.Texture;
  brainN?: THREE.Texture;
  seafan?: THREE.Texture;
  skin?: THREE.Texture;
  skinN?: THREE.Texture;
}

const FILES: Record<keyof ReefTextures, [string, boolean]> = {
  sand: ['sand_color.jpg', true],
  sandN: ['sand_normal.jpg', false],
  rubble: ['rubble_color.jpg', true],
  rubbleN: ['rubble_normal.jpg', false],
  rock: ['rock_color.jpg', true],
  rockN: ['rock_normal.jpg', false],
  coral: ['coral_color.jpg', true],
  coralN: ['coral_normal.jpg', false],
  brain: ['brain_color.jpg', true],
  brainN: ['brain_normal.jpg', false],
  seafan: ['seafan.png', true],
  skin: ['skin_color.jpg', true],
  skinN: ['skin_normal.jpg', false],
};

/** Loads every texture; any that fail are left out and the surface falls back to plain colour. */
export async function loadReefTextures(renderer: THREE.WebGLRenderer): Promise<ReefTextures> {
  const loader = new THREE.TextureLoader();
  const aniso = Math.min(8, renderer.capabilities.getMaxAnisotropy());
  const out: ReefTextures = {};
  await Promise.all(
    (Object.keys(FILES) as (keyof ReefTextures)[]).map(async (key) => {
      const [file, color] = FILES[key];
      try {
        const tex = await loader.loadAsync(new URL(`textures/${file}`, document.baseURI).href);
        tex.wrapS = tex.wrapT = THREE.RepeatWrapping;
        tex.anisotropy = aniso;
        if (color) tex.colorSpace = THREE.SRGBColorSpace;
        // Sea fans use their shape's own coordinates (metres): a fine lattice needs a few repeats per metre.
        if (key === 'seafan') tex.repeat.set(2.2, 2.2);
        out[key] = tex;
      } catch {
        // A missing texture never blocks the reef.
      }
    }),
  );
  return out;
}

export interface SurfaceOptions {
  /** Animated sunlight caustics on upward-facing surfaces. */
  caustics?: number;
  /** Triplanar mapping of `map` and `normalMap`: texture tiles per metre. */
  tiles?: number;
  /** A second texture set, blended in by the geometry's `aBlend` attribute (0–1). */
  blend?: { map: THREE.Texture; normalMap?: THREE.Texture; tiles: number };
}

/**
 * Patches a standard material with object-space triplanar texturing, an
 * optional second blended texture set, and caustics. Safe to call with
 * missing textures: only what is present is used.
 */
export function surface(mat: THREE.MeshStandardMaterial, opts: SurfaceOptions) {
  const tri = !!opts.tiles && !!(mat.map || mat.normalMap);
  const blend = tri && opts.blend ? opts.blend : null;
  const caustics = opts.caustics ?? 0;
  mat.customProgramCacheKey = () => `oe-surface:${tri ? 1 : 0}:${blend ? 1 : 0}:${blend?.normalMap ? 1 : 0}:${caustics ? 1 : 0}`;
  mat.onBeforeCompile = (shader) => {
    shader.uniforms.uTime = sharedTime;
    shader.uniforms.uSun = sunlight;
    shader.uniforms.uCausticStrength = { value: caustics };
    shader.uniforms.uTiles = { value: opts.tiles ?? 1 };
    if (blend) {
      shader.uniforms.uBlendMap = { value: blend.map };
      shader.uniforms.uBlendNormal = { value: blend.normalMap ?? null };
      shader.uniforms.uBlendTiles = { value: blend.tiles };
    }
    const defs = `${tri ? '#define OE_TRI\n' : ''}${blend ? '#define OE_BLEND\n' : ''}${blend?.normalMap ? '#define OE_BLEND_N\n' : ''}${caustics ? '#define OE_CAUSTICS\n' : ''}`;
    shader.vertexShader = shader.vertexShader
      .replace(
        '#include <common>',
        `#include <common>
${defs}varying vec3 vOeWorld;
varying vec3 vOeObj;
varying vec3 vOeObjN;
#ifdef OE_BLEND
attribute float aBlend;
varying float vOeBlend;
#endif`,
      )
      .replace(
        '#include <begin_vertex>',
        `#include <begin_vertex>
vOeWorld = (modelMatrix * vec4(transformed, 1.0)).xyz;
vOeObj = transformed;
vOeObjN = objectNormal;
#ifdef OE_BLEND
vOeBlend = aBlend;
#endif`,
      );
    shader.fragmentShader = shader.fragmentShader
      .replace(
        '#include <common>',
        `#include <common>
${defs}varying vec3 vOeWorld;
varying vec3 vOeObj;
varying vec3 vOeObjN;
uniform float uTime;
uniform float uSun;
uniform float uCausticStrength;
uniform float uTiles;
uniform mat3 normalMatrix;
#ifdef OE_BLEND
varying float vOeBlend;
uniform sampler2D uBlendMap;
uniform float uBlendTiles;
#endif
#ifdef OE_BLEND_N
uniform sampler2D uBlendNormal;
#endif
vec3 oeTriW(vec3 n) { vec3 w = pow(abs(n), vec3(4.0)); return w / (w.x + w.y + w.z); }
vec4 oeTri(sampler2D t, vec3 p, vec3 w) { return texture2D(t, p.zy) * w.x + texture2D(t, p.xz) * w.y + texture2D(t, p.xy) * w.z; }
vec3 oeTriN(sampler2D t, vec3 p, vec3 w, vec2 s) {
  vec2 a = (texture2D(t, p.zy).xy * 2.0 - 1.0) * s;
  vec2 b = (texture2D(t, p.xz).xy * 2.0 - 1.0) * s;
  vec2 c = (texture2D(t, p.xy).xy * 2.0 - 1.0) * s;
  return vec3(0.0, a.y, a.x) * w.x + vec3(b.x, 0.0, b.y) * w.y + vec3(c.x, c.y, 0.0) * w.z;
}
float oeCaustic(vec2 p, float t) {
  float c = 0.0;
  c += sin(p.x * 2.1 + t * 0.9 + sin(p.y * 1.7 + t * 0.6));
  c += sin(p.y * 2.6 - t * 0.7 + sin(p.x * 1.3 - t * 0.5));
  c += sin((p.x + p.y) * 1.6 + t * 0.4);
  c = c / 3.0;
  return pow(max(0.0, 1.0 - abs(c) * 1.6), 4.0);
}`,
      )
      .replace(
        '#include <map_fragment>',
        `#if defined(OE_TRI) && defined(USE_MAP)
  vec3 oeWt = oeTriW(normalize(vOeObjN));
  vec4 sampledDiffuseColor = oeTri(map, vOeObj * uTiles, oeWt);
  #ifdef OE_BLEND
  sampledDiffuseColor = mix(sampledDiffuseColor, oeTri(uBlendMap, vOeObj * uBlendTiles, oeWt), clamp(vOeBlend, 0.0, 1.0));
  #endif
  diffuseColor *= sampledDiffuseColor;
#else
  #include <map_fragment>
#endif`,
      )
      .replace(
        '#include <normal_fragment_maps>',
        `#if defined(OE_TRI) && defined(USE_NORMALMAP)
  vec3 oeN0 = normalize(vOeObjN);
  vec3 oeWn = oeTriW(oeN0);
  vec3 oeD = oeTriN(normalMap, vOeObj * uTiles, oeWn, normalScale);
  #ifdef OE_BLEND_N
  oeD = mix(oeD, oeTriN(uBlendNormal, vOeObj * uBlendTiles, oeWn, normalScale), clamp(vOeBlend, 0.0, 1.0));
  #endif
  normal = normalize(normalMatrix * normalize(oeN0 + oeD)) * faceDirection;
#else
  #include <normal_fragment_maps>
#endif`,
      )
      .replace(
        '#include <emissivemap_fragment>',
        `#include <emissivemap_fragment>
#ifdef OE_CAUSTICS
  float oeUp = clamp(dot(normal, (viewMatrix * vec4(0.0, 1.0, 0.0, 0.0)).xyz), 0.0, 1.0);
  totalEmissiveRadiance += vec3(0.75, 0.95, 1.0) * oeCaustic(vOeWorld.xz * 2.4, uTime) * uCausticStrength * uSun * (0.3 + 0.7 * oeUp);
#endif`,
      );
  };
  mat.needsUpdate = true;
  return mat;
}

/** Gives every mesh under `root` a textured, triplanar surface (keeps each mesh's own colour). */
export function texturize(root: THREE.Object3D, map: THREE.Texture | undefined, normalMap: THREE.Texture | undefined, tiles: number, normalScale = 1) {
  if (!map && !normalMap) return;
  const done = new Set<THREE.Material>();
  root.traverse((o) => {
    const mesh = o as THREE.Mesh;
    const mat = mesh.material as THREE.MeshStandardMaterial | undefined;
    if (!mesh.isMesh || !mat || !('roughness' in mat) || done.has(mat) || (mesh as THREE.InstancedMesh).isInstancedMesh) return;
    done.add(mat);
    if (map) mat.map = map;
    if (normalMap) {
      mat.normalMap = normalMap;
      mat.normalScale.setScalar(normalScale);
    }
    surface(mat, { tiles });
  });
}
